$ErrorActionPreference = "Stop"
$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "4.9.7"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam $Version ScoresR completed-shoot preview..."

$payload = ""
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\scoresr_completed_preview_cli.py"),
    [Convert]::FromBase64String($payload)
)

Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8
Set-Location $ProjectRoot
& ".\.venv\Scripts\python.exe" -m py_compile ".\mntrapteam\scoresr_completed_preview_cli.py"
if ($LASTEXITCODE -ne 0) { throw "Syntax check failed." }

Write-Host ""
Write-Host "MNTrapTeam 4.9.7 installed."
Write-Host "Run:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.scoresr_completed_preview_cli'
